// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 비밀번호 찾기" (a9c0f3268c6c46ec8708c753aeedbe84).
// 오른쪽 카드는 비밀번호를 보여주는 대신 새 비밀번호를 설정하도록 바꿨다 (#37 결정, bcrypt라 원래 비밀번호는 알 수 없음).
// 모양은 아이디 찾기 화면과 같은 공통 조각(components/findAccount)으로 맞춘다.
// #189: docs/ui-guide.md 공통 값(uiStyles, FieldError)으로 바꿨다.
import { useRef, useState, type FormEvent, type Ref } from "react";
import { Link } from "react-router-dom";
import { resetPassword, verifyPasswordReset } from "../api/auth";
import { getErrorMessage } from "../api/client";
import { INPUT_PATTERNS, INPUT_RULES, formatPhoneInput, toPhoneDigits } from "../api/member";
import "./FindPassword.css";
import AccountLinks from "../components/AccountLinks";
import AuthHeader from "../components/AuthHeader";
import FieldError from "../components/FieldError";
import Footer from "../components/Footer";
import { HEADER_BUTTON_CLASS, HEADER_BUTTON_COLOR } from "../components/headerStyles";
import {
  FieldHint,
  FieldLabel,
  FindCard,
  FindCardFooter,
  FindCardHeader,
  FindPageHeading,
  NoticeBox,
  StatusMessage,
  type HintTone,
} from "../components/findAccount/FindAccountParts";
import { buttonClass, FOCUS, INPUT, PAGE_BACKGROUND } from "../components/uiStyles";

type Step = "locked" | "form" | "done";
type Notice = { tone: HintTone; text: string };

const IDLE_NOTICE: Notice = { tone: "idle", text: "아이디와 전화번호를 입력하고 본인 확인을 눌러 주세요." };

function PasswordInput({
  id,
  label,
  value,
  onChange,
  placeholder,
  invalid,
  inputRef,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  invalid: boolean;
  inputRef?: Ref<HTMLInputElement>;
}) {
  const [visible, setVisible] = useState(false);
  return (
    <>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <div className="relative">
        <input
          aria-invalid={invalid}
          autoComplete="new-password"
          className={`${INPUT.base} pr-11 ${invalid ? INPUT.error : ""}`}
          id={id}
          maxLength={12}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          ref={inputRef}
          type={visible ? "text" : "password"}
          value={value}
        />
        {/* 로그인·개인정보 수정 화면의 보기/숨기기 버튼과 같은 모양 */}
        <button
          aria-label={visible ? "비밀번호 숨기기" : "비밀번호 보기"}
          aria-pressed={visible}
          className={`absolute inset-y-0 right-1 my-1 px-2 flex items-center rounded text-devin-gray hover:text-devin-ink ${FOCUS}`}
          onClick={() => setVisible((v) => !v)}
          type="button"
        >
          <span className="material-symbols-outlined text-[18px] leading-none" aria-hidden="true">
            {visible ? "visibility_off" : "visibility"}
          </span>
        </button>
      </div>
    </>
  );
}

export default function FindPassword() {
  const [loginId, setLoginId] = useState("");
  const [phone, setPhone] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [step, setStep] = useState<Step>("locked");
  const [notice, setNotice] = useState<Notice>(IDLE_NOTICE);
  const [resetError, setResetError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const newPasswordRef = useRef<HTMLInputElement>(null);

  const loginIdValid = INPUT_PATTERNS.loginId.test(loginId);
  const phoneValid = INPUT_PATTERNS.phone.test(toPhoneDigits(phone));
  const canVerify = step === "locked" && loginIdValid && phoneValid && !submitting;
  const newPasswordValid = INPUT_PATTERNS.password.test(newPassword);
  const passwordsMatch = newPasswordValid && newPassword === confirmPassword;
  const canReset = step === "form" && passwordsMatch && !submitting;

  function editAccount(setter: (value: string) => void, value: string) {
    setter(value);
    if (notice.tone === "error") setNotice(IDLE_NOTICE);
  }

  async function handleVerify(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canVerify) return;
    setSubmitting(true);
    try {
      await verifyPasswordReset(loginId, toPhoneDigits(phone));
      setNotice({ tone: "ok", text: "본인 확인을 마쳤어요. 오른쪽에서 새 비밀번호를 설정해 주세요." });
      setStep("form");
      // 오른쪽 카드가 그려진 다음 새 비밀번호 칸으로 커서를 옮긴다.
      requestAnimationFrame(() => newPasswordRef.current?.focus());
    } catch (err) {
      setNotice({ tone: "error", text: getErrorMessage(err) });
    } finally {
      setSubmitting(false);
    }
  }

  async function handleReset(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canReset) return;
    setSubmitting(true);
    setResetError(null);
    try {
      await resetPassword(loginId, toPhoneDigits(phone), newPassword);
      setStep("done");
    } catch (err) {
      setResetError(getErrorMessage(err));
    } finally {
      setSubmitting(false);
    }
  }

  const loginIdInvalid = loginId !== "" && !loginIdValid;
  const phoneInvalid = phone !== "" && !phoneValid;
  const newPasswordTone: HintTone = newPassword === "" ? "idle" : newPasswordValid ? "ok" : "error";
  const confirmInvalid = confirmPassword !== "" && !passwordsMatch;

  return (
    <div id="page-find-password">
      <div className={`${PAGE_BACKGROUND} min-h-screen flex flex-col justify-between text-devin-ink antialiased`}>
        <AuthHeader>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.white}`} to="/login">
            로그인
          </Link>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.yellow}`} to="/signup">
            회원가입
          </Link>
        </AuthHeader>

        <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-10 flex flex-col justify-center">
          <FindPageHeading
            description="가입할 때 등록한 아이디와 전화번호로 본인 확인을 하면 새 비밀번호를 설정할 수 있어요."
            title="비밀번호 찾기"
          />

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-stretch">
            {/* 왼쪽 카드: 계정 정보 입력 + 본인 확인 */}
            <FindCard className="justify-between">
              <div>
                <FindCardHeader title="계정 정보 입력" />

                <form className="space-y-5" noValidate onSubmit={handleVerify}>
                  <div>
                    <FieldLabel htmlFor="user-id">아이디</FieldLabel>
                    <input
                      aria-invalid={loginIdInvalid}
                      autoComplete="username"
                      className={`${INPUT.base} ${loginIdInvalid ? INPUT.error : ""}`}
                      disabled={step !== "locked"}
                      id="user-id"
                      maxLength={12}
                      onChange={(e) => editAccount(setLoginId, e.target.value)}
                      placeholder="아이디 입력"
                      type="text"
                      value={loginId}
                    />
                    <FieldHint tone={loginIdInvalid ? "error" : "idle"}>
                      {loginIdInvalid ? INPUT_RULES.loginId : "가입할 때 만든 아이디"}
                    </FieldHint>
                  </div>
                  <div>
                    <FieldLabel htmlFor="user-phone">전화번호</FieldLabel>
                    <input
                      aria-invalid={phoneInvalid}
                      autoComplete="tel"
                      className={`${INPUT.base} ${phoneInvalid ? INPUT.error : ""} font-mono tracking-wider`}
                      disabled={step !== "locked"}
                      id="user-phone"
                      inputMode="numeric"
                      maxLength={13}
                      onChange={(e) => editAccount(setPhone, formatPhoneInput(e.target.value))}
                      placeholder="010-0000-0000"
                      type="tel"
                      value={phone}
                    />
                    <FieldHint tone={phoneInvalid ? "error" : "idle"}>
                      {phoneInvalid
                        ? "01로 시작하는 10~11자리 숫자를 입력해 주세요."
                        : "숫자만 입력하면 하이픈이 자동으로 들어가요."}
                    </FieldHint>
                  </div>

                  <NoticeBox tone={notice.tone}>{notice.text}</NoticeBox>

                  {/* 본인 확인 뒤에는 오른쪽 [비밀번호 변경]이 주요 버튼이 되도록 보조 버튼으로 바꾼다 (한 화면에 주요 버튼 하나) */}
                  <button
                    className={`${buttonClass(step === "locked" ? "primary" : "secondary")} w-full`}
                    disabled={!canVerify}
                    type="submit"
                  >
                    {submitting && step === "locked" ? "확인 중..." : "본인 확인"}
                  </button>
                </form>
              </div>

              <FindCardFooter>
                <AccountLinks current="find-password" />
              </FindCardFooter>
            </FindCard>

            {/* 오른쪽 카드: 본인 확인 전(잠김) → 새 비밀번호 입력 → 변경 완료 */}
            <FindCard className="min-h-[360px]">
              {step === "locked" && (
                <div className="flex-1 flex flex-col">
                  <FindCardHeader title="새 비밀번호 설정" />
                  <StatusMessage icon="lock" title="왼쪽에서 본인 확인을 먼저 해 주세요.">
                    아이디와 가입할 때 등록한 전화번호가 일치하면
                    <br />새 비밀번호를 설정할 수 있어요.
                  </StatusMessage>
                </div>
              )}

              {step === "form" && (
                <form className="flex-1 flex flex-col justify-between" noValidate onSubmit={handleReset}>
                  <div>
                    <FindCardHeader title="새 비밀번호 설정" />
                    <p className="text-sm font-medium text-devin-gray mb-5">
                      본인 확인을 마쳤어요. 사용할 새 비밀번호를 입력해 주세요.
                    </p>
                    <div className="space-y-5">
                      <div>
                        <PasswordInput
                          id="new-password"
                          inputRef={newPasswordRef}
                          invalid={newPasswordTone === "error"}
                          label="새 비밀번호"
                          onChange={setNewPassword}
                          placeholder="8~12자, 영문·숫자·_ . -"
                          value={newPassword}
                        />
                        <FieldHint tone={newPasswordTone}>
                          {newPasswordTone === "ok" ? "사용할 수 있는 비밀번호예요." : INPUT_RULES.password}
                        </FieldHint>
                      </div>
                      <div>
                        <PasswordInput
                          id="new-password-confirm"
                          invalid={confirmInvalid}
                          label="새 비밀번호 확인"
                          onChange={setConfirmPassword}
                          placeholder="한 번 더 입력"
                          value={confirmPassword}
                        />
                        {confirmPassword !== "" && (
                          <FieldHint tone={passwordsMatch ? "ok" : "error"}>
                            {passwordsMatch ? "비밀번호가 일치해요." : "비밀번호가 일치하지 않아요."}
                          </FieldHint>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="space-y-3 mt-6">
                    <FieldError message={resetError ?? undefined} />
                    <button className={`${buttonClass("primary")} w-full`} disabled={!canReset} type="submit">
                      {submitting ? "변경 중..." : "비밀번호 변경"}
                    </button>
                    <Link className={`${buttonClass("secondary")} w-full`} to="/find-id">
                      아이디 찾기
                    </Link>
                  </div>
                </form>
              )}

              {step === "done" && (
                <div className="flex-1 flex flex-col">
                  <FindCardHeader title="비밀번호 변경 완료" />
                  <StatusMessage icon="check_circle" title="비밀번호를 바꿨어요." tone="success">
                    새 비밀번호로 다시 로그인해 주세요.
                    <br />
                    다른 기기에서 로그인된 상태도 함께 로그아웃돼요.
                  </StatusMessage>
                  <Link className={`${buttonClass("primary")} w-full mt-auto`} to="/login">
                    로그인하러 가기
                    <span className="material-symbols-outlined text-[18px] leading-none" aria-hidden="true">
                      arrow_forward
                    </span>
                  </Link>
                </div>
              )}
            </FindCard>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}
